if (meu.length < 12) {
    node.warn("Defina MEU_NUMERO nas propriedades da aba (ex.: 5541999998888)");
    node.status({ fill: "red", shape: "ring", text: "MEU_NUMERO não definido" });
    return null;
}
const agora = new Date().toLocaleString("pt-BR", { timeZone: "America/Sao_Paulo" });
msg.payload = { numero: meu, mensagem: "✅ Teste do Node-RED funcionando - " + agora };
node.status({ fill: "green", shape: "dot", text: "enviado " + agora });
return msg;

const meu = String(env.get("MEU_NUMERO") || "").replace(/\D/g, "");
if (meu.length < 12) {
    node.warn("Defina MEU_NUMERO nas propriedades da aba (ex.: 5541999998888)");
    node.status({ fill: "red", shape: "ring", text: "MEU_NUMERO não definido" });
    return null;
}
const p = msg.payload || {};
if (p.grupo) return null;                       // ignora grupos
const de = String(p.numero || "");
if (de.slice(-8) !== meu.slice(-8)) return null; // só aceita comandos do seu número

const texto = String(p.mensagem || "").trim().toLowerCase();
let resposta = null;
if (texto === "ping") resposta = "🤖 pong";
else if (texto === "hora") resposta = "🤖 Agora são " + new Date().toLocaleTimeString("pt-BR", { timeZone: "America/Sao_Paulo" });
else if (texto === "ajuda") resposta = "🤖 Comandos de teste: ping, hora, ajuda";
if (!resposta) return null;                      // não é comando: não responde (evita loop)

node.status({ fill: "blue", shape: "dot", text: "comando: " + texto });
msg.payload = { numero: meu, mensagem: resposta };
return msg;
